#pragma optimize("s", on)
namespace std {
template <class OutputIter, class Size, class T> inline
OutputIter __fastcall fill_n(OutputIter first, Size n, const T& val)
{
    for (; n > 0; --n, ++first)
        *first = val;
    return first;
}
